#!/usr/bin/env bash
set -euo pipefail
mkdir -p test299-native-evidence
apd_aapt="$(find "$ANDROID_HOME/build-tools" -type f -name aapt | sort -V | tail -1)"
apd_test_apk=android/build/outputs/apk/androidTest/debug/android-debug-androidTest.apk
apd_package="$("$apd_aapt" dump badging hotbar-restart-evidence/after.apk | sed -n "s/^package: name='\([^']*\)'.*/\1/p")"
apd_test_package="$("$apd_aapt" dump badging "$apd_test_apk" | sed -n "s/^package: name='\([^']*\)'.*/\1/p")"
adb shell am force-stop "$apd_package"
adb install -r -d hotbar-restart-evidence/after.apk
adb install -r -d "$apd_test_apk"
# Fresh emulator fixture for the complete retained suite, after the no-clear cold-restart gate.
adb shell pm clear "$apd_package"
adb shell rm -rf /sdcard/Pictures/APD-Test-Visuals
adb logcat -c
timeout --signal=TERM --kill-after=30 1080 adb shell am instrument -w -r -e class 'com.shatteredpixel.shatteredpixeldungeon.android.UimsdRestoreDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.AndroidBackDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.PlayRunDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.RunSetupDifficultyDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.ApdSettingsClickDeviceTest#adultHumorControlWorksWithoutAnAgeProviderAndReopensWithSavedChoice,com.shatteredpixel.shatteredpixeldungeon.android.ApdSettingsClickDeviceTest#grudgeControlsRespondToActualTouches,com.shatteredpixel.shatteredpixeldungeon.android.ApdSettingsClickDeviceTest#communityMenuOpensEveryPreviewAndReturnsWithoutStackingWindows,com.shatteredpixel.shatteredpixeldungeon.android.ApdSettingsClickDeviceTest#categorizedSettingsPreserveControlsAndRespondOnSmallScreens,com.shatteredpixel.shatteredpixeldungeon.android.AboutDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.UimsdScreensDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.UimsdResourcesDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.ChangesVisualDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.ReleaseNotesNavigationDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.CustomRulesNoticeDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.TopScoresDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.CustomScoreDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.TitleMenuLayoutDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.ClassSaveSlotsDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.PileExaminationDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.UimsdSearchDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.UimsdColumnsModalDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.UimsdChartDeviceTest,com.shatteredpixel.shatteredpixeldungeon.android.UimsdResearchDeviceTest' "${apd_test_package}/androidx.test.runner.AndroidJUnitRunner" > test299-native-evidence/instrumentation.txt
adb logcat -d > test299-native-evidence/logcat.txt
python3 - <<'CHECK'
import pathlib,re,json
p=pathlib.Path('test299-native-evidence');s=(p/'instrumentation.txt').read_text()
assert 'OK (50 tests)' in s and 'FAILURES!!!' not in s,s[-12000:]
records=[];current={}
for line in s.splitlines():
    if line.startswith('INSTRUMENTATION_STATUS: '):
        key,_,value=line[len('INSTRUMENTATION_STATUS: '):].partition('=');current[key]=value
    elif line.startswith('INSTRUMENTATION_STATUS_CODE: '):
        code=int(line.split(': ',1)[1]);
        if code==0: records.append((current.get('class'),current.get('test')))
        current={}
assert len(records)==50 and len(set(records))==50,records
(p/'result.json').write_text(json.dumps({'source':'d274cfce8b14b48766be2cbe1cb5aa63558f9a23','exact_produced_apk':True,'application_rebuilt':False,'passed':50,'cases':records},indent=2))
CHECK
for apd_visual_name in apd-settings-categories.png apd-settings-gameplay.png apd-settings-rules.png apd-settings-hotbar.png apd-settings-visibility.png apd-settings-history.png apd-settings-advanced.png apd-settings-narrow.png uimsd-equipment-window.png uimsd-run-dna.png uimsd-research-evidence.png uimsd-luck-lab.png uimsd-discoveries.png uimsd-investigation.png uimsd-chart-values.png uimsd-chart-counts.png hotbar-controls.png daily-earned-score.png daily-earned-score-scrolled.png custom-scoring-vision.png custom-scoring-vision-narrow.png boss-key-no-promotion.png victory-no-promotion.png options-confirmations.png waterskin-confirm.png known-trap-confirm.png main-title-layout.png main-title-hidden.png main-title-restored.png custom-rules-live-drag.png custom-rules-live-summary.png healing-conversion-setting.png cleric-first-run.png cleric-empty-slot-picker.png cleric-four-slot-touch.png apd-changes.png apd-technical-changes.png release-notes-navigation.png release-notes-reopened.png spd-changes-reference.png apd-build-22.png apd-build-37.png apd-codex-test-67.png tiles-original-2.png tiles-enhanced-2.png tiles-original-4.png tiles-enhanced-4.png stairs-shortcut.png stairs-highlight.png uimsd-empty-home.png uimsd-home.png uimsd-demo-info.png uimsd-text-values.png uimsd-sort-keys.png chalice-preview.png blacksmith-rewards.png blacksmith-reward-detail.png healing-confirmation.png healing-threshold-settings.png metamorph-five-choices.png metamorph-choice-detail.png custom-rules-notice.png custom-rules-notice-narrow.png custom-rules-notice-narrow-scrolled.png custom-rules-equipment.png custom-rules-touch-gestures.png top-scores-main-menu.png top-scores-rankings.png custom-score-neutral.png custom-score-pending.png custom-score-unknown.png custom-score-narrow.png custom-score-narrow-before.png; do
  adb exec-out cat "/sdcard/Pictures/APD-Test-Visuals/${apd_visual_name}" > "test299-native-evidence/${apd_visual_name}"
done
python3 tools/validate_android_visuals.py test299-native-evidence apd-settings-categories.png apd-settings-gameplay.png apd-settings-rules.png apd-settings-hotbar.png apd-settings-visibility.png apd-settings-history.png apd-settings-advanced.png apd-settings-narrow.png uimsd-equipment-window.png uimsd-run-dna.png uimsd-research-evidence.png uimsd-luck-lab.png uimsd-discoveries.png uimsd-investigation.png uimsd-chart-values.png uimsd-chart-counts.png hotbar-controls.png daily-earned-score.png daily-earned-score-scrolled.png custom-scoring-vision.png custom-scoring-vision-narrow.png boss-key-no-promotion.png victory-no-promotion.png options-confirmations.png waterskin-confirm.png known-trap-confirm.png main-title-layout.png main-title-hidden.png main-title-restored.png custom-rules-live-drag.png custom-rules-live-summary.png healing-conversion-setting.png cleric-first-run.png cleric-empty-slot-picker.png cleric-four-slot-touch.png apd-changes.png apd-technical-changes.png release-notes-navigation.png release-notes-reopened.png spd-changes-reference.png apd-build-22.png apd-build-37.png apd-codex-test-67.png tiles-original-2.png tiles-enhanced-2.png tiles-original-4.png tiles-enhanced-4.png stairs-shortcut.png stairs-highlight.png uimsd-empty-home.png uimsd-home.png uimsd-demo-info.png uimsd-text-values.png uimsd-sort-keys.png chalice-preview.png blacksmith-rewards.png blacksmith-reward-detail.png healing-confirmation.png healing-threshold-settings.png metamorph-five-choices.png metamorph-choice-detail.png custom-rules-notice.png custom-rules-notice-narrow.png custom-rules-notice-narrow-scrolled.png custom-rules-equipment.png custom-rules-touch-gestures.png top-scores-main-menu.png top-scores-rankings.png custom-score-neutral.png custom-score-pending.png custom-score-unknown.png custom-score-narrow.png custom-score-narrow-before.png
